anywhere;line-height:1.55;font-size:14px;user-select:text}.task-summary{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:290px}.empty{text-align:center;padding:18px 8px}.computer{font-size:35px;line-height:1.3}.voice{font-size:12px;color:var(--atom-accent,#007aff)}.save-warning{display:flex;gap:6px;align-items:center}.save-warning button{padding:4px 8px;min-height:30px;white-space:nowrap}.task-list button{width:100%;text-align:left;margin-top:6px;display:block}.approval{border:1px solid #f0ba66}.approval .output{font-size:12px;max-height:90px;overflow:auto}a{color:var(--atom-accent,#007aff)}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
