/* ATOM device UI / 2026-10. A fixed canvas, restrained chrome, content-led tools. */
*{box-sizing:border-box;scrollbar-width:none!important}*::-webkit-scrollbar{display:none!important;width:0!important;height:0!important}
html,body{width:100%;height:100%;margin:0;overflow:hidden!important;overscroll-behavior:none}
body{font-family:-apple-system,BlinkMacSystemFont,"Noto Sans CJK SC",sans-serif;-webkit-font-smoothing:antialiased;letter-spacing:-.2px;background:var(--atom-paper,#f4f5f7);color:var(--atom-ink,#202124)}
button,input,select,textarea{font:inherit}button{transition:background-color 130ms ease,transform 130ms ease}button:active{transform:scale(.98)}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--atom-accent,#007aff);outline-offset:2px}
.screen,body>main{height:100%;max-height:100vh;overflow:hidden;padding:18px 22px;gap:10px;min-height:0}
.header,body>main>header{height:40px;min-height:40px;flex-shrink:0;gap:12px}
h1{font-size:27px;line-height:1.18;letter-spacing:-1px;font-weight:700;margin:0}h2{font-size:18px;letter-spacing:-.45px}h3{font-size:15px;letter-spacing:-.2px}
.header button,body>main>header>button{min-height:32px;border-radius:18px;padding:6px 12px;font-size:12px}
button{min-height:36px;border-radius:11px;font-weight:550;padding:8px 12px}button.secondary{background:var(--atom-card,#fff);color:var(--atom-accent,#007aff)}
input,select,textarea{border:0!important;background:var(--atom-card,#fff);border-radius:12px;min-width:0;color:inherit}input,select{min-height:36px;padding:8px 11px}
.scroll,.list,section#list{min-height:0;overscroll-behavior:contain;overflow-x:hidden}
.card{border-radius:16px;padding:14px;margin-bottom:10px;box-shadow:none}.card h2{margin-bottom:7px}.muted,small{color:var(--atom-secondary-text,#74777f);font-size:11px;line-height:1.55}
.notice{padding:8px 11px;line-height:1.45;font-size:11px;border-radius:10px;flex-shrink:0}.notice.error{background:#fff0ed;color:#a63931}
.segments,.mode-selector{padding:3px;gap:3px;border-radius:11px;background:var(--atom-line,#e8e9ee);flex-shrink:0}.segments button,.mode-selector button{min-height:28px;font-size:12px;padding:4px 8px;border-radius:8px}.segments button[aria-pressed=true],.mode-selector button[aria-pressed=true]{box-shadow:0 1px 4px #20212412;font-weight:650}
.field{margin:8px 0}.field>span{font-size:11px;letter-spacing:.1px;margin-bottom:4px}.empty{min-height:0}.empty h2{font-size:21px;letter-spacing:-.6px}.empty p{font-size:12px;line-height:1.7}.actions{gap:7px}.pre{font-size:11px;line-height:1.6}
/* Notes: a quiet notebook, not a stack of dashboard widgets. */
body[data-atom-app=quick-notes] .screen{gap:9px}
body[data-atom-app=quick-notes] .screen>.notice:not(.error){background:transparent;color:var(--atom-secondary-text,#74777f);padding:0 2px;min-height:16px;font-size:10px}
body[data-atom-app=quick-notes] .scroll>.card:not(.empty){border-radius:0;background:transparent;border-bottom:1px solid var(--atom-line,#dedfe5);padding:12px 3px;margin:0}
body[data-atom-app=quick-notes] .note-open{font-size:17px;font-weight:650;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
body[data-atom-app=quick-notes] .note-editor{background:var(--atom-card,#fff);border-radius:16px;font-size:17px;line-height:1.8;padding:17px 18px;box-shadow:inset 3px 0 0 #eac56a}
body[data-atom-app=quick-notes] .note-body{line-height:1.75}body[data-atom-app=quick-notes] .row>.actions button{min-height:30px;background:transparent;padding:4px 8px}
/* Market: compact editorial rows. Search/categories stay still; only the catalog moves. */
body[data-atom-app=market] .catalog{display:flex;flex-direction:column;gap:0;background:var(--atom-card,#fff);border-radius:16px;padding:0 13px}
body[data-atom-app=market] .work{display:grid;grid-template-columns:43px 1fr;grid-template-rows:auto auto auto;column-gap:11px;min-height:96px;flex-shrink:0;padding:13px 0;border-radius:0;border-bottom:1px solid var(--atom-line,#e6e7eb);background:transparent;width:100%}
body[data-atom-app=market] .work:last-child{border-bottom:0}.work .mark{grid-row:1/4;width:42px;height:42px;border-radius:12px;font-size:24px;margin-top:2px;background:var(--atom-paper,#f3f4f7)}
body[data-atom-app=market] .work h2{font-size:17px;line-height:1.3;margin:0 0 4px;align-self:end}
body[data-atom-app=market] .work p{font-size:11px;line-height:1.4;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden}
body[data-atom-app=market] .work small{margin:0;padding-top:5px;font-size:10px}
body[data-atom-app=market] .search input{background:var(--atom-line,#e9eaef);height:36px}.search button{font-size:12px;min-height:36px;padding:6px 14px}
/* Library: install management as a clean indexed shelf. */
body[data-atom-app=app-library] main{padding:20px 23px;gap:13px}body[data-atom-app=app-library] #list{gap:0;background:var(--atom-card,#fff);border-radius:16px;padding:0 13px}
body[data-atom-app=app-library] .row{border-radius:0;background:transparent;border-bottom:1px solid var(--atom-line,#e5e6eb);padding:9px 0;min-height:61px;flex-shrink:0}
body[data-atom-app=app-library] .row:last-child{border:0}body[data-atom-app=app-library] .glyph{background:var(--atom-paper,#f4f5f8);border-radius:11px;width:39px;height:39px}body[data-atom-app=app-library] .glyph svg{width:25px;height:25px}body[data-atom-app=app-library] .name{font-size:15px;font-weight:600}body[data-atom-app=app-library] .pin{background:var(--atom-paper,#f4f5f8);color:var(--atom-accent,#007aff);border-radius:18px;min-height:30px;padding:5px 10px;font-size:10px}body[data-atom-app=app-library] #search{background:var(--atom-line,#e8e9ee);min-height:36px;padding:8px 12px}
/* Today: clear date hierarchy, generous checks, quiet secondary actions. */
body[data-atom-app=today] main{gap:9px;padding:18px 22px}body[data-atom-app=today] header{height:54px;min-height:54px}body[data-atom-app=today] .day{font-size:11px;letter-spacing:.25px;color:var(--atom-secondary-text,#767984);margin-bottom:3px}
body[data-atom-app=today] h1{font-size:30px}body[data-atom-app=today] header>button{background:var(--atom-accent,#007aff);color:white;font-size:12px;padding:7px 13px}
body[data-atom-app=today] .list{gap:0;background:var(--atom-card,#fff);border-radius:17px;padding:0 13px}body[data-atom-app=today] .item{padding:12px 0;min-height:65px;flex-shrink:0;background:transparent;border-radius:0;border-bottom:1px solid var(--atom-line,#e7e8eb);gap:11px}body[data-atom-app=today] .item:last-child{border-bottom:0}body[data-atom-app=today] .item strong{font-size:16px;line-height:1.4}body[data-atom-app=today] .item p{font-size:10px;color:var(--atom-secondary-text,#858893)}body[data-atom-app=today] .item>.small{font-size:10px;padding:4px 5px;min-height:30px;background:transparent}body[data-atom-app=today] .check{width:27px;height:27px;min-height:27px;border:1.5px solid var(--atom-line,#d7dce2);background:transparent;color:var(--atom-accent,#007aff)}body[data-atom-app=today] .done .check{background:var(--atom-accent,#007aff);color:#fff;border-color:transparent}
body[data-atom-app=today] .feedback{min-height:0;font-size:10px}body[data-atom-app=today] .feedback:empty{display:none}body[data-atom-app=today] footer{min-height:28px}body[data-atom-app=today] footer button{background:transparent;min-height:28px;padding:4px 8px;font-size:11px}
/* Sound: a small instrument. Controls recede; the four actual tracks keep their colors. */
body[data-atom-app=sound-lab] main{padding:18px 22px;gap:11px}body[data-atom-app=sound-lab] header{height:48px;min-height:48px}body[data-atom-app=sound-lab] h1{font-size:25px}body[data-atom-app=sound-lab] .play{border-radius:22px;padding:9px 16px;min-height:40px;font-size:13px}body[data-atom-app=sound-lab] header p{font-size:10px;margin-top:6px}
body[data-atom-app=sound-lab] .pages{display:flex;padding:3px;border-radius:10px;background:var(--atom-line,#e5e7ed);gap:2px}body[data-atom-app=sound-lab] .pages button{font-size:10px;min-height:24px;border-radius:7px;background:transparent;padding:3px 9px}body[data-atom-app=sound-lab] .pages .selected{background:var(--atom-card,#fff);box-shadow:0 1px 3px #0001}
body[data-atom-app=sound-lab] .sequencer{gap:7px;grid-template-columns:31px repeat(8,minmax(0,1fr))}body[data-atom-app=sound-lab] .step{border-radius:7px;background:#e3e6ed}body[data-atom-app=sound-lab] .step.on{background:#377df6}body[data-atom-app=sound-lab] .step[data-track="1"].on{background:#9d7ed9}body[data-atom-app=sound-lab] .step[data-track="2"].on{background:#e6ac53}body[data-atom-app=sound-lab] .step[data-track="3"].on{background:#4faf9f}body[data-atom-app=sound-lab] .controls{border-radius:13px;padding:9px 12px}body[data-atom-app=sound-lab] footer button{background:transparent;font-size:11px;padding:5px 8px;min-height:28px}body[data-atom-app=sound-lab] footer{gap:5px}
/* A status companion: larger character, fewer boxes. */
body[data-atom-app=task-pal] main{padding:19px 22px;gap:10px}body[data-atom-app=task-pal] .body{grid-template-columns:181px 1fr;gap:16px}body[data-atom-app=task-pal] .buddy{background:transparent;padding:17px 4px;justify-content:center}body[data-atom-app=task-pal] .face{background:var(--atom-card,#fff);height:98px;width:146px;border-radius:31px;box-shadow:0 7px 24px #29354808}body[data-atom-app=task-pal] .face:before{left:70px}body[data-atom-app=task-pal] .face:after{left:73px}body[data-atom-app=task-pal] .face b{left:64px}body[data-atom-app=task-pal] .buddy h2{font-size:19px;margin-top:22px}body[data-atom-app=task-pal] .buddy p{font-size:11px;max-height:52px;overflow:hidden}body[data-atom-app=task-pal] .tasks>select{height:34px;min-height:34px;font-size:11px}body[data-atom-app=task-pal] .task{border-radius:12px;padding:10px 11px;margin-bottom:7px;border:1px solid transparent}body[data-atom-app=task-pal] .task[aria-pressed=true]{border-color:var(--atom-accent,#007aff)}body[data-atom-app=task-pal] footer{font-size:9px}body[data-atom-app=task-pal] #error:empty{display:none}
/* Canvas applications retain meaningful scene colors and an unobtrusive control dock. */
body[data-atom-app=pixel-lab] header{top:17px;left:22px;right:22px}body[data-atom-app=pixel-lab] strong{font-size:24px;font-weight:700;letter-spacing:-.8px}body[data-atom-app=pixel-lab] header small{font-size:10px;letter-spacing:.2px}body[data-atom-app=pixel-lab] footer{bottom:16px;left:20px;right:20px;background:var(--atom-card,#fff);border-radius:16px;padding:6px;gap:3px;box-shadow:0 4px 18px #1a223208}body[data-atom-app=pixel-lab] footer button{font-size:11px;min-height:32px;padding:6px 10px;background:transparent}body[data-atom-app=pixel-lab] footer button:first-child{background:var(--atom-accent,#007aff)}body[data-atom-app=pixel-lab] #hint{bottom:73px;font-size:10px}body[data-atom-app=pixel-lab] input{width:51px}
body[data-atom-app=official-companion] .top{top:20px;left:23px;right:23px}body[data-atom-app=official-companion] .title{font-size:24px;letter-spacing:-.8px;font-weight:700}body[data-atom-app=official-companion] .caption{font-size:11px;margin-top:6px}body[data-atom-app=official-companion] .controls{bottom:20px;left:50%;right:auto;transform:translateX(-50%);background:var(--atom-card,#fff);border-radius:20px;padding:4px;gap:3px}body[data-atom-app=official-companion] .controls button{min-width:68px;min-height:32px;padding:6px 13px;font-size:12px;border-radius:17px;background:transparent}body[data-atom-app=official-companion] .controls button[aria-pressed=true]{background:var(--atom-accent,#007aff)}body[data-atom-app=official-companion] .hint{bottom:75px;font-size:10px}
/* Computer: distinct compose/history panes, fixed form, scrolling only for actual task output. */
body[data-atom-app=my-computer] .screen{gap:9px;padding:17px 22px}body[data-atom-app=my-computer] .selectors{gap:10px}body[data-atom-app=my-computer] .card{padding:12px 14px}body[data-atom-app=my-computer] .field{margin:6px 0}body[data-atom-app=my-computer] .mode-selector{margin-bottom:8px}body[data-atom-app=my-computer] #prompt{min-height:56px;height:62px;padding:10px 12px;font-size:15px;line-height:1.5;background:var(--atom-paper,#f3f4f7)}body[data-atom-app=my-computer] .voice{font-size:10px}body[data-atom-app=my-computer] .row button{min-height:34px;font-size:12px}body[data-atom-app=my-computer] .task-list button{background:var(--atom-card,#fff);border-bottom:1px solid var(--atom-line,#e5e7ec);padding:14px;border-radius:10px;margin-top:6px}body[data-atom-app=my-computer] .workbench-tabs{display:flex;gap:17px;height:30px;min-height:30px;align-items:start;border-bottom:1px solid var(--atom-line,#e3e5eb)}.workbench-tabs button{background:transparent;color:var(--atom-secondary-text,#777b84);border-radius:0;min-height:28px;padding:2px 0 7px;font-size:12px}.workbench-tabs button[aria-pressed=true]{color:var(--atom-ink,#202124);border-bottom:2px solid var(--atom-accent,#007aff)}body[data-atom-app=my-computer] .fixed-compose{overflow:hidden;display:flex;flex-direction:column;flex:1;min-height:0}body[data-atom-app=my-computer] .fixed-compose>.card{margin-bottom:0;flex:1;min-height:0}body[data-atom-app=my-computer] .fixed-compose .empty{display:flex;flex-direction:column;justify-content:center;gap:6px}.content-scroll{min-height:0;flex:1;overflow-y:auto;overscroll-behavior:contain}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;animation:none!important}}
